export default async function({}: NodeInputs, { req }: NodeScriptOptions): Promise<NodeOutput> {
  const forwarded = req.headers?.['x-forwarded-for'];
  if (forwarded) {
    const first = typeof forwarded === 'string' ? forwarded.split(',')[0].trim() : forwarded[0];
    return first;
  }
  return req.headers?.['cf-connecting-ip'] || req.ip || req.connection?.remoteAddress || 'unknown';
}

import { Firestore } from '@google-cloud/firestore';

export default async function fingerprintDbQuery({ projectId, collectionName, ip, cookieId, fingerprint }: NodeInputs): Promise<NodeOutput> {
  const db = new Firestore({ projectId });
  const col = db.collection(collectionName);

  const queries = [
    col.where('cookie_id', '==', cookieId).get(),
    col.where('fingerprint', '==', fingerprint).get(),
    col.where('ip', '==', ip).get()
  ];

  const snapshots = await Promise.all(queries);
  const seen = new Set<string>();
  const records: any[] = [];

  for (const snap of snapshots) {
    for (const doc of snap.docs) {
      if (!seen.has(doc.id)) {
        seen.add(doc.id);
        records.push({ id: doc.id, ...doc.data() });
      }
    }
  }

  return { records, count: records.length };
}

export default async function identityMatchScorer({ records, ip, cookieId, fingerprint, cookieWeight, fingerprintWeight, ipWeight, matchThreshold }: NodeInputs): Promise<NodeOutput> {
  const cw = cookieWeight ?? 40;
  const fw = fingerprintWeight ?? 35;
  const iw = ipWeight ?? 25;
  const threshold = matchThreshold ?? 75;

  if (!records || records.length === 0) {
    return { isExisting: false, bestMatch: null, bestScore: 0, allScores: [] };
  }

  const allScores = records.map((record: any) => {
    let score = 0;
    if (record.cookie_id && record.cookie_id === cookieId) score += cw;
    if (record.fingerprint && record.fingerprint === fingerprint) score += fw;
    if (record.ip && record.ip === ip) score += iw;
    return { id: record.id, user_id: record.user_id, score };
  });

  allScores.sort((a: any, b: any) => b.score - a.score);

  const best = allScores[0];
  const isExisting = best.score >= threshold;

  return {
    isExisting,
    bestMatch: isExisting ? records.find((r: any) => r.id === best.id) : null,
    bestScore: best.score,
    allScores
  };
}

