import { Firestore, FieldValue } from '@google-cloud/firestore'
import { v4 as uuidv4 } from 'uuid'

export default async function createNewIdentity({ projectId, collectionName, ip, cookieId, fingerprint }: NodeInputs): Promise<NodeOutput> {
  const db = new Firestore({ projectId })
  const userId = uuidv4()
  const now = new Date()
  const usageMonth = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`

  await db.collection(collectionName).add({
    user_id: userId,
    cookie_id: cookieId,
    fingerprint,
    ip,
    created_at: FieldValue.serverTimestamp(),
    last_seen: FieldValue.serverTimestamp(),
    visit_count: 1,
    usage_count: 0,
    usage_month: usageMonth,
  })

  return { user_id: userId, status: 'new', usage_count: 0, usage_month: usageMonth }
}

