import { Firestore, FieldValue } from '@google-cloud/firestore'

export default async function updateExistingIdentity({ projectId, collectionName, documentId, ip, userId }: NodeInputs): Promise<NodeOutput> {
  const db = new Firestore({ projectId })
  const docRef = db.collection(collectionName).doc(documentId)
  const doc = await docRef.get()
  const data = doc.data() || {}

  const now = new Date()
  const currentMonth = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`

  // Reset usage if month rolled over
  const usageMonth = data.usage_month || ''
  const usageCount = usageMonth === currentMonth ? (data.usage_count ?? 0) : 0

  const updateFields = {
    ip,
    last_seen: FieldValue.serverTimestamp(),
    visit_count: FieldValue.increment(1),
  }

  // If month changed, reset the usage fields on the doc
  if (usageMonth !== currentMonth) {
    updateFields.usage_count = 0
    updateFields.usage_month = currentMonth
  }

  await docRef.update(updateFields)

  return { user_id: userId, status: 'recognized', usage_count: usageCount, usage_month: currentMonth }
}

